#define main legacy_main
#include "../mask-cuda/main.cu"
#undef main
#include <vector>
#include <string>
struct F{int m,n,barg,b,rad,blocks;std::vector<int>seq,centers,a,gold[6];int *di,*ds,*dc,*out[6];F(int f){m=f==1?37:19;n=f==1?29:17;barg=f==1?3:-1;b=barg<=0?1:barg;rad=m/4;blocks=barg<=0?n*m/256:n*m;seq.resize(n);centers.resize(n);a.resize(m*n*b);if(f==1){srand(123);for(int&z:seq)z=rand()%(m/2);for(int&z:centers)z=rand()%m;for(int&z:a)z=rand()%(m*n);}else{for(int j=0;j<n;j++){seq[j]=(j%3==0?0:j%3==1?m:m/2);centers[j]=(j%3==0?0:j%3==1?m-1:m/2);}for(size_t i=0;i<a.size();i++)a[i]=2*i+17;}for(auto&g:gold)g.resize(a.size());sequenceMaskKernel_cpu(n,m,b,a.data(),seq.data(),-1,gold[0].data());windowMaskKernel_cpu(n,m,b,a.data(),centers.data(),rad,-1,gold[1].data());upperMaskKernel_cpu(n,m,b,a.data(),-1,gold[2].data());lowerMaskKernel_cpu(n,m,b,a.data(),-1,gold[3].data());upperDiagMaskKernel_cpu(n,m,b,a.data(),-1,gold[4].data());lowerDiagMaskKernel_cpu(n,m,b,a.data(),-1,gold[5].data());for(int batch=0;batch<b;batch++)for(int row=0;row<n;row++)for(int col=0;col<m;col++){int ix=batch*n*m+row*m+col;bool keep[]={col<seq[row],abs(col-centers[row])<=rad,col<=row,col>=row,col<row,col>row};for(int mode=0;mode<6;mode++)if(gold[mode][ix]!=(keep[mode]?a[ix]:-1))abort();}cudaMalloc(&di,a.size()*4);cudaMalloc(&ds,n*4);cudaMalloc(&dc,n*4);cudaMemcpy(di,a.data(),a.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(ds,seq.data(),n*4,cudaMemcpyHostToDevice);cudaMemcpy(dc,centers.data(),n*4,cudaMemcpyHostToDevice);for(auto&v:out)cudaMalloc(&v,a.size()*4);}void launch(int mode){switch(mode){case 0:sequenceMaskKernel<<<blocks,256>>>(n,m,b,di,ds,-1,out[mode]);break;case 1:windowMaskKernel<<<blocks,256>>>(n,m,b,di,dc,rad,-1,out[mode]);break;case 2:upperMaskKernel<<<blocks,256>>>(n,m,b,di,-1,out[mode]);break;case 3:lowerMaskKernel<<<blocks,256>>>(n,m,b,di,-1,out[mode]);break;case 4:upperDiagMaskKernel<<<blocks,256>>>(n,m,b,di,-1,out[mode]);break;case 5:lowerDiagMaskKernel<<<blocks,256>>>(n,m,b,di,-1,out[mode]);break;}}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;std::vector<F>fs;std::vector<int>prefix;for(int f=1;f<=2;f++){fs.emplace_back(f);auto&q=fs.back();prefix.insert(prefix.end(),{q.m,q.n,q.barg,q.b,q.rad});prefix.insert(prefix.end(),q.seq.begin(),q.seq.end());prefix.insert(prefix.end(),q.centers.begin(),q.centers.end());prefix.insert(prefix.end(),q.a.begin(),q.a.end());for(int m=0;m<6;m++)q.launch(m);}cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int r=0;r<rep;r++)for(auto&q:fs)for(int m=0;m<6;m++)q.launch(m);cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;std::vector<int>got;bool ok=cudaGetLastError()==cudaSuccess;for(auto&q:fs)for(int m=0;m<6;m++){std::vector<int>g(q.a.size());cudaMemcpy(g.data(),q.out[m],g.size()*4,cudaMemcpyDeviceToHost);ok&=g==q.gold[m];got.insert(got.end(),g.begin(),g.end());}auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":0.0,\"timing_region\":\"all6maskoperators_twofixtures_12kernelbatch_sourcegridpolicy\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),rep,path.c_str(),art.size());if(!ok)return 2;}for(auto&q:fs){cudaFree(q.di);cudaFree(q.ds);cudaFree(q.dc);for(auto v:q.out)cudaFree(v);}}
